\begin{definition}
\label{def:6-41-extra-1}




For a positive continuous function $\delta:M\to\mathbb{R}$, maps $F,\widetilde F:M\to\mathbb{R}^k$ are $\delta$-close if
\[
|F(x)-\widetilde F(x)|<\delta(x)
\qquad\text{for every }x\in M.
\]
\end{definition}

